     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Context;
    11→
    12→    # Phase 1 polymorphic node classes
    13→    use Chalk::IR::Node::Base;
    14→    use Chalk::IR::Node::Constant;
    15→    use Chalk::IR::Node::Start;
    16→    use Chalk::IR::Node::Return;
    17→    use Chalk::IR::Node::Add;
    18→    use Chalk::IR::Node::Subtract;
    19→    use Chalk::IR::Node::Multiply;
    20→    use Chalk::IR::Node::Divide;
    21→    use Chalk::IR::Node::Negate;
    22→    use Chalk::IR::Node::Not;
    23→    use Chalk::IR::Node::PreIncrement;
    24→    use Chalk::IR::Node::PreDecrement;
    25→    use Chalk::IR::Node::PostIncrement;
    26→    use Chalk::IR::Node::PostDecrement;
    27→    use Chalk::IR::Node::Reference;
    28→    use Chalk::IR::Node::ScalarDeref;
    29→    use Chalk::IR::Node::VariableRead;
    30→    use Chalk::IR::Node::GT;
    31→    use Chalk::IR::Node::LT;
    32→    use Chalk::IR::Node::EQ;
    33→    use Chalk::IR::Node::NE;
    34→    use Chalk::IR::Node::LE;
    35→    use Chalk::IR::Node::GE;
    36→    use Chalk::IR::Node::If;
    37→    use Chalk::IR::Node::Proj;
    38→    use Chalk::IR::Node::Region;
    39→    use Chalk::IR::Node::Phi;
    40→    use Chalk::IR::Node::Loop;
    41→
    42→    field $graph :reader;
    43→    field $context :reader;  # Context-as-closure for variable memory
    44→    field $node_counter :reader = 0;
    45→    field $current_control :reader;  # Current control flow node
    46→    field $loop_depth = 0;   # Current loop nesting depth for label namespacing
    47→    field $loop_modified_vars = [];  # Stack of sets tracking modified vars per loop depth
    48→
    49→    ADJUST {
    50→        $graph = Chalk::IR::Graph->new();
    51→        $context = Chalk::IR::Context->empty_context();
    52→    }
    53→
    54→    # Generate unique node ID
    55→    method next_node_id() {
    56→        my $id = "node_$node_counter";
    57→        $node_counter++;
    58→        return $id;
    59→    }
    60→
    61→    # Set current control flow node
    62→    method set_control($ctrl) {
    63→        $current_control = $ctrl;
    64→    }
    65→
    66→    # Set context (for testing and manual context updates)
    67→    method set_context($ctx) {
    68→        $context = $ctx;
    69→    }
    70→
    71→    # Create Start node for a function/method
    72→    method build_start_node($function_name = 'main', $params = undef) {
    73→        $params //= [];
    74→        my $node_id = $self->next_node_id();
    75→        my $empty_inputs = [];
    76→        my $start = Chalk::IR::Node::Start->new(
    77→            id            => $node_id,
    78→            inputs        => $empty_inputs,
    79→            function_name => $function_name,
    80→            params        => $params,
    81→        );
    82→        $graph->add_node($start);
    83→        $self->set_control($start->id);
    84→
    85→        # Create Proj nodes for each parameter and register in context
    86→        my $param_count = scalar($params->@*);
    87→        for my $i (0..($param_count - 1)) {
    88→            my $param_name = $params->[$i];
    89→            my $proj = $self->build_proj_node($start, $i, $param_name);
    90→            # Register parameter Proj in context with lexical: namespace
    91→            my $label = "lexical:$param_name";
    92→            $context = Chalk::IR::Context->extend_context($context, $label, $proj);
    93→        }
    94→
    95→        return $start;
    96→    }
    97→
    98→    # Create Constant node
    99→    method build_constant_node($value, $type = 'Int') {
   100→        die "build_constant_node: value is undefined" unless defined($value);
   101→
   102→        my $node_id = $self->next_node_id();
   103→        my $constant = Chalk::IR::Node::Constant->new(
   104→            id            => $node_id,
   105→            inputs        => [$current_control],
   106→            value         => $value,
   107→            type          => $type,
   108→        );
   109→        $graph->add_node($constant);
   110→        return $constant;
   111→    }
   112→
   113→    # Create Return node
   114→    # If $control is undef, uses current_control. Otherwise uses provided control.
   115→    method build_return_node($value_node, $control = undef) {
   116→        die "build_return_node: value_node is undefined" unless defined($value_node);
   117→
   118→        # Check that value_node is an IR node object
   119→        my $ref_type = ref($value_node) || 'SCALAR';
   120→        my $prefix = substr($ref_type, 0, 15);
   121→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
   122→        unless ($ref_type && $is_node) {
   123→            die "build_return_node: value_node is not an IR node object (got $ref_type)";
   124→        }
   125→
   126→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   127→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   128→
   129→        my $node_id = $self->next_node_id();
   130→        my $return = Chalk::IR::Node::Return->new(
   131→            id            => $node_id,
   132→            inputs        => [$ctrl, $value_node->id],
   133→            value_id      => $value_node->id,
   134→            control_id    => $ctrl,
   135→        );
   136→        $graph->add_node($return);
   137→        return $return;
   138→    }
   139→
   140→    # Set control input for an existing node
   141→    method set_node_control($node, $control_id) {
   142→        my $inputs = $node->inputs;
   143→        $inputs->[0] = $control_id;  # Control is always first input
   144→    }
   145→
   146→    # Create arithmetic operation nodes
   147→    method build_add_node($left_node, $right_node) {
   148→        die "build_add_node: left_node is undefined" unless defined($left_node);
   149→        die "build_add_node: right_node is undefined" unless defined($right_node);
   150→        die "build_add_node: left_node is not an IR node object" unless ref($left_node) && ref($left_node) =~ /^Chalk::IR::Node/;
   151→        die "build_add_node: right_node is not an IR node object" unless ref($right_node) && ref($right_node) =~ /^Chalk::IR::Node/;
   152→
   153→        my $node_id = $self->next_node_id();
   154→        my $add = Chalk::IR::Node::Add->new(
   155→            id => $node_id,
   156→            inputs => [$current_control, $left_node->id, $right_node->id],
   157→            left_id => $left_node->id,
   158→            right_id => $right_node->id,
   159→        );
   160→        $graph->add_node($add);
   161→        return $add;
   162→    }
   163→
   164→    method build_multiply_node($left_node, $right_node) {
   165→        my $node_id = $self->next_node_id();
   166→        my $mul = Chalk::IR::Node::Multiply->new(
   167→            id => $node_id,
   168→            inputs => [$current_control, $left_node->id, $right_node->id],
   169→            left_id => $left_node->id,
   170→            right_id => $right_node->id,
   171→        );
   172→        $graph->add_node($mul);
   173→        return $mul;
   174→    }
   175→
   176→    method build_sub_node($left_node, $right_node) {
   177→        my $node_id = $self->next_node_id();
   178→        my $sub = Chalk::IR::Node::Subtract->new(
   179→            id => $node_id,
   180→            inputs => [$current_control, $left_node->id, $right_node->id],
   181→            left_id => $left_node->id,
   182→            right_id => $right_node->id,
   183→        );
   184→        $graph->add_node($sub);
   185→        return $sub;
   186→    }
   187→
   188→    method build_divide_node($left_node, $right_node) {
   189→        my $node_id = $self->next_node_id();
   190→        my $div = Chalk::IR::Node::Divide->new(
   191→            id => $node_id,
   192→            inputs => [$current_control, $left_node->id, $right_node->id],
   193→            left_id => $left_node->id,
   194→            right_id => $right_node->id,
   195→        );
   196→        $graph->add_node($div);
   197→        return $div;
   198→    }
   199→
   200→    # Generate label with loop depth if inside a loop
   201→    method make_variable_label($var_name) {
   202→        if ($loop_depth > 0) {
   203→            return "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   204→        }
   205→        return "lexical:$var_name";
   206→    }
   207→
   208→    # Create Store node (variable assignment)
   209→    method build_store_node($var_name, $value_node, $control = undef) {
   210→        # Store variable using lexical: namespace in context
   211→        # Inside loops, use loop depth in label: lexical:loop_0:$var
   212→        # Store the IR node object directly, not the node ID
   213→        my $label = $self->make_variable_label($var_name);
   214→        $context = Chalk::IR::Context->extend_context($context, $label, $value_node);
   215→
   216→        # Track this variable as modified if we're in a loop
   217→        if ($loop_depth > 0 && scalar($loop_modified_vars->@*) > 0) {
   218→            my $current_loop_vars = $loop_modified_vars->[-1];
   219→            $current_loop_vars->{$var_name} = 1;
   220→        }
   221→
   222→        return $value_node;
   223→    }
   224→
   225→    # Load node (variable read)
   226→    method build_load_node($var_name) {
   227→        # Retrieve variable using lexical: namespace from context
   228→        # Try loop-scoped label first, then fall back to outer scope
   229→        # Context now stores IR node objects directly, not node IDs
   230→        my $node;
   231→
   232→        # Try current loop depth first (search from innermost to outermost)
   233→        if ($loop_depth > 0) {
   234→            my $depth = $loop_depth - 1;
   235→            while ($depth >= 0) {
   236→                my $label = "lexical:loop_${depth}:$var_name";
   237→                $node = $context->($label);
   238→                last if defined($node);
   239→                $depth--;
   240→            }
   241→        }
   242→
   243→        # Fall back to non-loop lexical scope
   244→        $node //= $context->("lexical:$var_name");
   245→
   246→        # Return the node directly from context (no graph lookup needed)
   247→        return $node;
   248→    }
   249→
   250→    # Create Proj node (projection from MultiNode like Start)
   251→    method build_proj_node($source_node, $index, $label) {
   252→        my $node_id = $self->next_node_id();
   253→        my $proj = Chalk::IR::Node::Proj->new(
   254→            id            => $node_id,
   255→            inputs        => [$source_node->id],
   256→            index         => $index,
   257→            label         => $label,
   258→        );
   259→        $graph->add_node($proj);
   260→        return $proj;
   261→    }
   262→
   263→    # Comparison nodes
   264→    method build_greater_node($left_node, $right_node) {
   265→        my $node_id = $self->next_node_id();
   266→        my $cmp = Chalk::IR::Node::GT->new(
   267→            id            => $node_id,
   268→            inputs        => [$current_control, $left_node->id, $right_node->id],
   269→            left_id       => $left_node->id,
   270→            right_id      => $right_node->id,
   271→        );
   272→        $graph->add_node($cmp);
   273→        return $cmp;
   274→    }
   275→
   276→    method build_less_node($left_node, $right_node) {
   277→        my $node_id = $self->next_node_id();
   278→        my $cmp = Chalk::IR::Node::LT->new(
   279→            id            => $node_id,
   280→            inputs        => [$current_control, $left_node->id, $right_node->id],
   281→            left_id       => $left_node->id,
   282→            right_id      => $right_node->id,
   283→        );
   284→        $graph->add_node($cmp);
   285→        return $cmp;
   286→    }
   287→
   288→    method build_equal_node($left_node, $right_node) {
   289→        my $node_id = $self->next_node_id();
   290→        my $cmp = Chalk::IR::Node::EQ->new(
   291→            id            => $node_id,
   292→            inputs        => [$current_control, $left_node->id, $right_node->id],
   293→            left_id       => $left_node->id,
   294→            right_id      => $right_node->id,
   295→        );
   296→        $graph->add_node($cmp);
   297→        return $cmp;
   298→    }
   299→
   300→    method build_greater_or_equal_node($left_node, $right_node) {
   301→        my $node_id = $self->next_node_id();
   302→        my $cmp = Chalk::IR::Node::GE->new(
   303→            id            => $node_id,
   304→            inputs        => [$current_control, $left_node->id, $right_node->id],
   305→            left_id       => $left_node->id,
   306→            right_id      => $right_node->id,
   307→        );
   308→        $graph->add_node($cmp);
   309→        return $cmp;
   310→    }
   311→
   312→    method build_less_or_equal_node($left_node, $right_node) {
   313→        my $node_id = $self->next_node_id();
   314→        my $cmp = Chalk::IR::Node::LE->new(
   315→            id            => $node_id,
   316→            inputs        => [$current_control, $left_node->id, $right_node->id],
   317→            left_id       => $left_node->id,
   318→            right_id      => $right_node->id,
   319→        );
   320→        $graph->add_node($cmp);
   321→        return $cmp;
   322→    }
   323→
   324→    method build_not_equal_node($left_node, $right_node) {
   325→        my $node_id = $self->next_node_id();
   326→        my $cmp = Chalk::IR::Node::NE->new(
   327→            id            => $node_id,
   328→            inputs        => [$current_control, $left_node->id, $right_node->id],
   329→            left_id       => $left_node->id,
   330→            right_id      => $right_node->id,
   331→        );
   332→        $graph->add_node($cmp);
   333→        return $cmp;
   334→    }
   335→
   336→    # Unary operation nodes
   337→    method build_not_node($operand_node) {
   338→        my $node_id = $self->next_node_id();
   339→        my $not = Chalk::IR::Node::Not->new(
   340→            id            => $node_id,
   341→            inputs        => [$current_control, $operand_node->id],
   342→            operand_id    => $operand_node->id,
   343→        );
   344→        $graph->add_node($not);
   345→        return $not;
   346→    }
   347→
   348→    method build_negate_node($operand_node) {
   349→        my $node_id = $self->next_node_id();
   350→        my $negate = Chalk::IR::Node::Negate->new(
   351→            id            => $node_id,
   352→            inputs        => [$current_control, $operand_node->id],
   353→            operand_id    => $operand_node->id,
   354→        );
   355→        $graph->add_node($negate);
   356→        return $negate;
   357→    }
