   503→    # Loop depth tracking methods
   504→    method begin_loop_tracking() {
   505→        # Increment loop depth when entering a loop
   506→        $loop_depth++;
   507→        # Push a new set to track modified variables at this loop depth
   508→        push $loop_modified_vars->@*, {};
   509→        return;
   510→    }
   511→
   512→    method end_loop_tracking() {
   513→        # Decrement loop depth when exiting a loop
   514→        if ($loop_depth > 0) {
   515→            $loop_depth--;
   516→            # Pop the modified variables set for this loop
   517→            pop $loop_modified_vars->@* if scalar($loop_modified_vars->@*) > 0;
   518→        }
   519→        return;
   520→    }
   521→
   522→    method is_tracking_loop() {
   523→        return $loop_depth > 0;
   524→    }
