   526→    method current_loop_depth() {
   527→        return $loop_depth;
   528→    }
   529→
   530→    method generate_loop_phi_nodes($loop_node) {
   531→        # Generate phi nodes for variables modified within the loop
   532→        # With context+labels approach, phi nodes are created for variables
   533→        # that exist both as 'lexical:$var' (pre-loop) and 'lexical:loop_N:$var' (in-loop)
   534→
   535→        my %phi_nodes;
   536→
   537→        # If we're not tracking a loop or have no modified vars, return empty
   538→        return \%phi_nodes unless scalar($loop_modified_vars->@*) > 0;
   539→
   540→        # Get the current loop's modified variables
   541→        my $modified_vars = $loop_modified_vars->[-1];
   542→
   543→        # For each modified variable, create a phi node
   544→        for my $var_name (keys($modified_vars->%*)) {
   545→            # Get pre-loop value (lexical:$var)
   546→            my $pre_loop_label = "lexical:$var_name";
   547→            my $pre_loop_value = $context->($pre_loop_label);
   548→
   549→            # Get loop-modified value (lexical:loop_N:$var where N = current depth - 1)
   550→            my $loop_label = "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   551→            my $loop_value = $context->($loop_label);
   552→
   553→            # Only create phi if both values exist
   554→            if (defined($pre_loop_value) && defined($loop_value)) {
   555→                # Build phi node with: control (loop), initial value, loop value
   556→                my $phi = $self->build_loop_phi_node(
   557→                    $loop_node,
   558→                    (ref($pre_loop_value) ? $pre_loop_value->id : $pre_loop_value),
   559→                    (ref($loop_value) ? $loop_value->id : $loop_value)
   560→                );
   561→                $phi_nodes{$var_name} = $phi;
   562→            }
   563→        }
   564→
   565→        return \%phi_nodes;
   566→    }
