   901→        # $module: module name (e.g., '5.42.0', 'experimental', 'Chalk::IR::Node')
   902→        # $imports: arrayref of imported symbols (empty for full import)
   903→
   904→        my $graph = $self->graph;
   905→        my $current_control = $self->current_control;
   906→
   907→        my $attributes = {
   908→            type => $type,
   909→            module => $module,
   910→            imports => $imports
   911→        };
   912→
   913→        my $node_id = $self->next_node_id();
   914→        my $use_stmt = Chalk::IR::Node->new(
   915→            id => $node_id,
   916→            op => 'UseStatement',
   917→            inputs => [$current_control],
   918→            attributes => $attributes,
   919→        );
   920→        $graph->add_node($use_stmt);
   921→        return $use_stmt;
   922→    }
   923→
   924→    # Reference operations (Issue #130 Phase 4)
   925→
   926→    # Create reference to a scalar variable: \$x
   927→    method build_scalar_ref_node($var_name) {
   928→        my $label = "lexical:$var_name";
   929→        # Look up the target node (might be object or ID)
   930→        my $target_node_or_id = $context->($label);
   931→        die "Cannot create reference to undefined variable $var_name" unless defined($target_node_or_id);
   932→
   933→        # Get the node ID for the dependency
   934→        my $target_node_id = ref($target_node_or_id) ? $target_node_or_id->id : $target_node_or_id;
   935→
   936→        my $node_id = $self->next_node_id();
   937→        my $reference = Chalk::IR::Node::Reference->new(
   938→            id             => $node_id,
   939→            inputs         => [$current_control, $target_node_id],  # Add target as dependency
   940→            target_context => $context,
   941→            target_label   => $label,
   942→        );
   943→        $graph->add_node($reference);
   944→        return $reference;
   945→    }
   946→
   947→    # Create reference to array element: \$arr[1]
   948→    method build_element_ref_node($collection_name, $index_node) {
   949→        # Get the collection from context (might be object or ID)
   950→        my $collection_label = "lexical:$collection_name";
   951→        my $collection_node_or_id = $context->($collection_label);
   952→
   953→        # Get the collection node
   954→        my $collection_node;
   955→        if (ref($collection_node_or_id)) {
   956→            $collection_node = $collection_node_or_id;
   957→        } else {
   958→            $collection_node = $graph->get_node($collection_node_or_id);
   959→        }
   960→
   961→        # Get the array context from the collection node
   962→        my $array_ctx = $collection_node->array_context;
   963→
   964→        # Get the index value - need to evaluate it
   965→        # For now, assume it's a constant node
   966→        my $index_val = $index_node->value;
   967→
   968→        # Create the reference pointing to the array context with index: label
   969→        my $label = Chalk::IR::Context->make_index_label($index_val);
   970→        my $node_id = $self->next_node_id();
   971→        my $reference = Chalk::IR::Node::Reference->new(
   972→            id             => $node_id,
   973→            inputs         => [$current_control, $collection_node->id, $index_node->id],
   974→            target_context => $array_ctx,
   975→            target_label   => $label,
   976→        );
   977→        $graph->add_node($reference);
   978→        return $reference;
   979→    }
   980→
   981→    # Dereference a scalar reference: $$ref
   982→    method build_scalar_deref_node($ref_var_name) {
   983→        # Get the reference from context (might be object or ID)
   984→        my $ref_label = "lexical:$ref_var_name";
   985→        my $ref_node_or_id = $context->($ref_label);
   986→
   987→        # Get the node ID
   988→        my $ref_id = ref($ref_node_or_id) ? $ref_node_or_id->id : $ref_node_or_id;
   989→
   990→        # Create ScalarDeref node
   991→        my $node_id = $self->next_node_id();
   992→        my $deref = Chalk::IR::Node::ScalarDeref->new(
   993→            id      => $node_id,
   994→            inputs  => [$current_control, $ref_id],
   995→            ref_id  => $ref_id,
   996→        );
   997→        $graph->add_node($deref);
   998→        return $deref;
   999→    }
  1000→
  1001→    # Read variable from context: helper for tests
  1002→    method build_variable_read_node($var_name) {
  1003→        my $label = "lexical:$var_name";
  1004→        my $node_id = $self->next_node_id();
  1005→        my $var_read = Chalk::IR::Node::VariableRead->new(
  1006→            id        => $node_id,
  1007→            inputs    => [$current_control],
  1008→            var_label => $label,
  1009→        );
  1010→        $graph->add_node($var_read);
  1011→        return $var_read;
  1012→    }
  1013→
  1014→    # Assign through a dereferenced reference: $$ref = value
  1015→    method build_scalar_deref_assign_node($ref_var_name, $value_node) {
  1016→        # Get the reference from context
  1017→        my $ref_label = "lexical:$ref_var_name";
  1018→        my $ref_node_or_id = $context->($ref_label);
  1019→
  1020→        # Might be node object or node ID depending on when it was stored
  1021→        my $ref_node;
  1022→        if (ref($ref_node_or_id)) {
  1023→            $ref_node = $ref_node_or_id;
  1024→        } else {
  1025→            $ref_node = $graph->get_node($ref_node_or_id);
  1026→        }
  1027→
  1028→        # Get the target label from the reference
  1029→        my $target_label = $ref_node->target_label;
  1030→
  1031→        # Extend the BUILDER's current context with the new value (node object, not ID)
  1032→        # This updates the variable that the reference points to
  1033→        $context = Chalk::IR::Context->extend_context(
  1034→            $context,
  1035→            $target_label,
  1036→            $value_node
  1037→        );
  1038→
  1039→        # Return the value node for chaining
  1040→        return $value_node;
  1041→    }
  1042→
  1043→}
  1044→
  1045→1;
  1046→

